function openCom(){open('<span class="v63-kick">COMMUNIQUÉ · À LIRE EN PRIORITÉ</span><h3>Paiement des tickets</h3><div class="v63-chips"><span>7.000 F ou 8.000 F</span><span>Avant le 15 octobre</span><span>Tee-shirt offert</span></div><p><b>Shalom</b> chers responsables de troupe et adjoints du district de Bouaflé, j’ose croire que mon message vous trouve en bonne santé. 🍀</p><p>Nous venons par ce message vous inviter à faire de votre mieux afin de vous acquitter de votre ticket de <b>7.000 F</b> ou de <b>8.000 F</b> en fonction de votre titre. Nous avons jusqu’au <b>15 octobre</b> pour solder notre paiement afin d’avoir nos tee-shirts gratuitement.</p><p class="v63-nb"><b>N.B :</b> les tee-shirts seront confectionnés à Abidjan et ce sont ceux qui paieront premièrement leur ticket qui seront servis. Les gens de la dernière minute auront leurs tee-shirts après le camp.</p><p>Nous attachons du prix à ce communiqué et nous souhaitons vivement son exécution.</p><p>Large diffusion à tous, cordialement…</p><p><b>Pour le camp du district 3 en 1, le SG</b></p><button type="button" class="v63-btn" id="v63Go">Je me pré-inscris</button>');$('v63Go').onclick=function(){close();if(window.openRegistration)openRegistration()}}
$('v63Tabs').onclick=function(e){var b=e.target.closest('button');if(!b)return;cur=+b.getAttribute('data-i');render()};
