window.v63AddMember=function(d){if(!d||!d.Name)return;var l=members(),id=String(d.Phone||d.Name).toLowerCase().replace(/\s+/g,''),o={id:id,n:d.Name,d:d.Group,p:d.Pass,c:d.Church},k=-1;l.forEach(function(m,i){if(m.id===id)k=i});if(k>=0)l[k]=o;else l.push(o);sv(MK,l);var i2=DS.indexOf(d.Group);if(i2>=0)cur=i2;render()};
function shareC(id,dn){var d=DEF[id]||{},t=(d.n||'Commissaire')+' — '+(d.p||'Commissaire')+' · '+(dn?'District de '+dn:'Bureau')+' · Camp de District 3 en 1',data={title:'Camp de District 3 en 1',text:t,url:location.href};if(navigator.share)navigator.share(data).catch(function(){});else if(navigator.clipboard)navigator.clipboard.writeText(t+' '+location.href).catch(function(){})}
var v72=null,v72d='',v72f='all',v72p=false;
function v72st(dn){var l=TR[dn].map(function(t,i){var c=ct(dn,i);return {t:t,i:i,c:c,f:!!(c.n||c.i)}});return l}
